pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 amount) internal {
        amount = 0;
        uint256 beforeCount;
        try c.depositsCount() returns (uint256 __r) { beforeCount = __r; } catch { return; }
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        uint256 afterCount;
        try c.depositsCount() returns (uint256 __r) { afterCount = __r; } catch { return; }
        assertTrue(!reverted && afterCount == beforeCount && address(c).balance == 0);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
